### 2. `localStorage` Cache

This method provides persistent caching across browser sessions. It is slightly slower than an in-memory cache and has a storage limit (around 5MB).

**Implementation:**
```javascript
const CACHE_KEY_PREFIX = 'weather_data_';
const CACHE_EXPIRATION_TIME = 60 * 60 * 1000; // 1 hour

async function getWeather(city) {
  const cacheKey = CACHE_KEY_PREFIX + city;

  // Check if the data is already cached and not expired
  const cachedData = localStorage.getItem(cacheKey);
  if (cachedData) {
    const { data, timestamp } = JSON.parse(cachedData);
    const currentTime = Date.now();
    if (currentTime - timestamp < CACHE_EXPIRATION_TIME) {
      console.log('Returning cached data for', city);
      return data;
    }
  }

  // Fetch data from the API
  const apiKey = 'my_api_key';
  const url = `https://api.openweathermap.org/data/2.5/weather?q=${city}&appid=${apiKey}`;
  const response = await fetch(url);
  if (!response.ok) {
    throw new Error(`HTTP error! status: ${response.status}`);
  }
  const data = await response.json();

  // Store the fetched data in localStorage with a timestamp
  localStorage.setItem(cacheKey, JSON.stringify({ data, timestamp: Date.now() }));

  return data;
}
```
